import kotlinx.coroutines.*

fun main() = runBlocking {
    try {
        coroutineScope {
            launch {
                delay(100)
                println("A")
            }
            launch {
                throw IllegalStateException("boom")
            }
        }
    } catch (e: IllegalStateException) {
        println("caught ${e.message}")
    }
    println("end")
}

class SyncViewModel(
    private val repository: SyncRepository,
) : ViewModel() {
    fun startSync() {
        viewModelScope.launch {
            while (true) {
                try {
                    repository.sync()
                    delay(5_000)
                } catch (e: Exception) {
                    Log.e("Sync", "failed", e)
                }
            }
        }
    }
}

